/**
 * Story 211 — the async-estimate review screen. The notification deep-links
 * here (data.path = /health/estimates/:id), and the submit flow navigates here
 * after enqueueing — so it must handle every job state:
 *   - queued  → spinner + poll (the user can leave; the push brings them back)
 *   - done    → the draft, editable, + Log / Discard
 *   - failed  → the raw error + Retry / Archive (fail loud)
 *
 * Story 423 (418 #7) — the result is a draft: library foods and proposed new
 * foods, none of them written. A meal opens in `<line-set-editor mode=draft>`,
 * a proposed single food in `<food-editor mode=estimate-draft>` first. Log saves
 * it through `POST /logs` (and `POST /meals` for "also save as a meal"), which is
 * where proposed foods are created, then records it on the job (`PATCH`).
 * Discard leaves nothing behind.
 *
 * Story 294 — a finished job then branches on its **disposition**, not on
 * `status`, which stays `'done'` forever:
 *   - undispositioned → the review above
 *   - accepted        → redirect to the day the meal is on
 *   - discarded       → the result read-only, with one "log it after all"
 * Rows that predate the column read as undispositioned; their outcome was never
 * recorded and was deliberately not guessed at (migration 033).
 */

const PROVENANCE_LABELS: Record<ResolutionProvenance, string> = {
    matched_library: 'library',
    matched_off: 'Open Food Facts',
    generated: 'AI estimate',
};

const PROVENANCE_CLASS: Record<ResolutionProvenance, string> = {
    matched_library: 'provenance-library',
    matched_off: 'provenance-off',
    generated: 'provenance-generated',
};

const POLL_MS = 2500;

/**
 * Story 321 — a poll that the network drops is not a failed estimate. The SW
 * gives a stalled API fetch 15 s (`networkFirstApi`) and then falls back to the
 * offline router, which does not own `estimate-jobs/:id` and so answers 503.
 * The screen used to render that as the outcome and stop polling, while the job
 * finished on the server seconds later — 33 times over two months, and all 32
 * jobs involved completed. So: keep asking, back off, and give up only after a
 * budget, with a way forward when we do.
 */
const MAX_POLL_FAILURES = 8;

/** Backoff cap. Each failed attempt already costs up to the SW's 15 s timeout. */
const POLL_BACKOFF_MAX_MS = 20000;

/** 2.5s, 5s, 10s, 20s, 20s… — doubling from the poll interval, capped. */
function retryDelayMs(consecutiveFailures: number): number {
    return Math.min(POLL_MS * 2 ** (consecutiveFailures - 1), POLL_BACKOFF_MAX_MS);
}

/** Id of the action-failure node, so a repeated failure replaces rather than stacks. */
const ACTION_ERROR_ID = 'estimate-action-error';

const PROVENANCE_KIND: Record<ResolutionProvenance, ProvenanceKind> = {
    matched_library: 'library',
    matched_off: 'off',
    generated: 'ai',
};

/** What a duplicate estimate does to the meal it matches (story 310), chosen before Log. */
type DuplicateChoice = 'log_onto' | 'update_amounts' | 'new_log';

/** One drafted food as a line: a library food links, a proposed one is created when saved. */
function draftLine(food: DraftFood, amount: number, resolution: Pick<IngredientResolution, 'provenance' | 'divergence'>): LineView {
    const key = uuidv7();
    const view = isLibraryFood(food) ? foodLineView(food, amount, key) : newFoodLineView(food, amount, key);
    // Story 319: a row that won a tie among disagreeing same-name rows says so first.
    return { ...view, badge: resolution.divergence ? 'differs' : PROVENANCE_KIND[resolution.provenance] };
}

function kcalOf(item: DraftFood, amount: number): number {
    return item.calories_per_base != null && item.base_amount > 0 ? (item.calories_per_base * amount) / item.base_amount : 0;
}

function resultKcal(result: EstimateJobResult): number {
    if (result.kind === 'food_item') return kcalOf(result.food_item, result.resolution.amount);
    return result.ingredients.reduce((sum, ing) => sum + kcalOf(ing.food_item, ing.amount), 0);
}

export class HealthEstimateReviewScreen extends HTMLElement implements ScreenComponent {
    private jobIdValue: string | null = null;
    private pendingHint = false;
    private content: HTMLElement | null = null;
    private pollTimer: number | null = null;
    private pollFailures = 0;
    private initialized = false;
    /** Story 372 (pwa-nutrition-20): a load is awaiting the job or the local submit. */
    private loading = false;
    /** Polling was live when the screen left, so coming back asks again. */
    private resumeOnConnect = false;
    private readonly log = createComponentLogger('health-estimate-review-screen');

    /**
     * No spinner: every action here either navigates away on success or is a
     * sub-second local call, so a loading flash would only strobe the screen.
     */
    setLoading(): void {}

    /**
     * Story 310 — these three were all no-ops, so a failed accept / archive /
     * retry logged and then showed the user nothing: the button appeared dead
     * and the obvious next move was to press it again. It matters now because
     * choosing a duplicate action can legitimately 409 (the meal it named no
     * longer has that ingredient set), and fail-loud is the house rule.
     */
    setError(err: unknown): void {
        const message = err instanceof Error ? (err.stack ?? err.message) : String(err);
        const root = this.content;
        if (!root) return;
        const pre = root.querySelector<HTMLElement>(`#${ACTION_ERROR_ID}`) ?? document.createElement('pre');
        pre.id = ACTION_ERROR_ID;
        pre.className = 'screen-error';
        pre.textContent = message;
        // Into the rendered section when there is one, so it sits with the
        // content it is about rather than below the page chrome.
        (root.querySelector<HTMLElement>('.estimate-review') ?? root).appendChild(pre);
    }

    clearStatus(): void {
        this.content?.querySelector(`#${ACTION_ERROR_ID}`)?.remove();
    }

    set jobId(value: string | null) {
        this.jobIdValue = value;
    }

    /** Story 221: the id is a client_submit_id from a locally-queued submit — resolve it via the submit store first. */
    set pending(value: boolean) {
        this.pendingHint = value;
    }

    connectedCallback(): void {
        if (this.initialized) {
            // A finished review is left as it was — a reload would drop its edits.
            if (this.resumeOnConnect) void this.load();
            return;
        }
        this.initialized = true;
        const page = buildSectionPage(this, 'Meal estimate', 'health', '/health');
        this.content = page.content;
        void this.load();
    }

    disconnectedCallback(): void {
        this.resumeOnConnect = this.loading || this.pollTimer !== null;
        this.stopPolling();
    }

    /** Story 372 (pwa-nutrition-20): a screen that is gone schedules nothing. */
    private schedulePoll(delayMs: number): void {
        if (!this.isConnected) return;
        this.pollTimer = window.setTimeout(() => void this.load(), delayMs);
    }

    private stopPolling(): void {
        if (this.pollTimer !== null) {
            clearTimeout(this.pollTimer);
            this.pollTimer = null;
        }
    }

    private async load(): Promise<void> {
        if (!this.jobIdValue) {
            this.renderMessage('No estimate selected.');
            return;
        }
        this.stopPolling();
        this.loading = true;
        try {
            let serverId = this.jobIdValue;
            if (this.pendingHint) {
                // Story 221: a submit still queued locally (offline, or not yet
                // shipped). While pending, show a queued state and nudge the
                // drain; once it ships, the local entry carries the server job
                // id and we poll that.
                const local = await getEstimateSubmit(this.jobIdValue).catch(() => null);
                if (!this.isConnected) return;
                if (local && local.status === 'pending') {
                    this.renderPendingSubmit();
                    void shipPendingEstimateSubmits().catch(() => { /* stays queued; retried on the next poll / online / sync */ });
                    this.schedulePoll(POLL_MS);
                    return;
                }
                if (local?.status === 'rejected') {
                    this.renderRejectedSubmit(local);
                    return;
                }
                if (local?.status === 'submitted' && local.server_job_id) serverId = local.server_job_id;
            }
            const job = await HealthService.findEstimateJob(serverId);
            if (!this.isConnected) return;
            // Story 321: a 404 is the server's, and terminal — the offline
            // router answers 503 for this route, never 404.
            if (!job) {
                this.pollFailures = 0;
                this.renderMessage('This estimate no longer exists.');
                return;
            }
            this.pollFailures = 0;
            this.renderJob(job);
            if (job.status === 'queued') {
                this.schedulePoll(POLL_MS);
            }
        } catch (err) {
            if (this.isConnected) this.onPollFailure(err);
        } finally {
            this.loading = false;
        }
    }

    /**
     * Story 321 — the job lives on the server and will finish whatever this
     * client just saw, so the honest answer to a failed poll is to ask again.
     * The queued copy stays put with a note appended; only an exhausted budget
     * turns it into an error, and that one comes with a way forward.
     */
    private onPollFailure(err: unknown): void {
        this.pollFailures += 1;
        this.log.warn('estimate poll failed', {
            attempt: this.pollFailures,
            error: err instanceof Error ? err.message : String(err),
        });

        if (this.pollFailures >= MAX_POLL_FAILURES) {
            this.renderUnreachable(err);
            return;
        }

        this.renderQueued('Lost contact with the server — still trying…');
        this.schedulePoll(retryDelayMs(this.pollFailures));
    }

    /** The budget ran out. Fail loud, but leave a button rather than a dead end. */
    private renderUnreachable(err: unknown): void {
        const section = this.reset();
        const pre = document.createElement('pre');
        pre.className = 'screen-error';
        pre.textContent = `Could not reach the server:\n${err instanceof Error ? err.message : 'Failed to load the estimate.'}`;
        section.appendChild(pre);
        section.appendChild(this.actions([
            {
                label: 'Try again',
                primary: true,
                onClick: () => {
                    this.pollFailures = 0;
                    void this.load();
                },
            },
        ]));
    }

    private reset(): HTMLElement {
        const root = this.content!;
        root.replaceChildren();
        const section = document.createElement('div');
        section.className = 'estimate-review';
        root.appendChild(section);
        return section;
    }

    private renderMessage(message: string): void {
        const section = this.reset();
        const p = document.createElement('p');
        p.className = 'screen-error';
        p.textContent = message;
        section.appendChild(p);
    }

    private renderJob(job: EstimateJob): void {
        // `status` describes the pipeline and comes first: a queued or failed
        // job has no outcome to have a disposition about.
        if (job.status === 'queued') return this.renderQueued(undefined, job);
        if (job.status === 'failed') return this.renderFailed(job);
        if (!job.result) return this.renderMessage('Estimate finished but produced no result.');

        // Story 294: branch on what the job BECAME, not on `status` — which
        // stays 'done' forever and so kept offering a live Log-it button for a
        // meal that was already on the day.
        if (job.disposition === 'accepted') return this.showWhatItBecame(job);
        if (job.disposition === 'discarded') return this.renderDiscarded(job, job.result);
        return this.renderDone(job, job.result);
    }

    /**
     * Already logged — go to where the meal actually lives. `replace`, so the
     * estimate URL does not linger directly behind the day: a push would leave
     * one back press landing on a screen whose only job is to redirect again,
     * which reads as back doing nothing.
     */
    private showWhatItBecame(job: EstimateJob): void {
        this.renderMessage('Already logged — opening the day…');
        navigate(`/health/day/${encodeURIComponent(job.date)}`, { history: 'replace' });
    }

    /**
     * Thrown away, and nothing was created. The result is shown read-only with
     * one action: this is a fresh decision, not an outstanding review, so there
     * is no ingredient editing and no second Discard.
     */
    private renderDiscarded(job: EstimateJob, result: EstimateJobResult): void {
        const section = this.reset();

        const note = document.createElement('p');
        note.className = 'estimate-review-hint';
        note.id = 'estimate-discarded-note';
        note.textContent = 'You discarded this estimate. Nothing was logged.';
        section.appendChild(note);

        this.renderResultSummary(section, job, result);
        section.appendChild(this.actions([
            // A fresh decision: the draft opens as it would have, nothing was created.
            { label: 'Log it after all', primary: true, onClick: () => this.renderDone(job, result) },
        ]));
    }

    /** `note` (story 321): a poll is failing, but the estimate is still coming — say so under the wait copy, not instead of it. */
    private renderQueued(note?: string, job?: EstimateJob): void {
        const section = this.reset();
        const p = document.createElement('p');
        p.className = 'screen-loading';
        p.textContent = 'Estimating your meal… you can leave this screen — we’ll notify you when it’s ready.';
        section.appendChild(p);
        if (note) {
            const hint = document.createElement('p');
            hint.className = 'estimate-review-hint';
            hint.id = 'estimate-poll-retry-note';
            hint.textContent = note;
            section.appendChild(hint);
        }
        if (job?.image_path) void this.showPhotoHeld(section, job);
    }

    /**
     * Story 427 — the server holds a photo estimate queued while Local AI runs
     * the text-only setup (no vision projector). Say so, and offer both ways
     * out: turn Local AI off (the photo then runs on the app setup), or cancel.
     */
    private async showPhotoHeld(section: HTMLElement, job: EstimateJob): Promise<void> {
        const hint = document.createElement('p');
        hint.className = 'estimate-review-hint';
        hint.id = 'estimate-photo-held';
        let state: LocalAiState;
        try {
            state = await AiService.getLocalAi();
        } catch (err) {
            if (!section.isConnected) return;
            hint.textContent = `Could not read Local AI: ${err instanceof Error ? err.message : String(err)}`;
            section.appendChild(hint);
            return;
        }
        if (!section.isConnected || state.mode === 'off' || state.setup !== 'text') return;
        hint.textContent = 'Local AI is running the text-only setup, which can’t read photos — this estimate only runs after Local AI is turned off.';
        section.append(hint, this.actions([
            { label: 'Turn Local AI off now', primary: true, onClick: () => this.turnOffLocalAi() },
            { label: 'Cancel estimate', onClick: () => this.cancel(job.id) },
        ]));
    }

    private turnOffLocalAi(): void {
        void safeExec(this, this.log, async () => {
            await AiService.setLocalAi('off');
            await this.load();
        });
    }

    /** Story 427: the server cancels a job that has not run (failed + discarded), so Retry still works. */
    private cancel(jobId: string): void {
        void safeExec(this, this.log, async () => {
            await HealthService.archiveEstimateJob(jobId);
            await this.load();
        });
    }

    /** Story 221: the submit is queued on-device and hasn't reached the server yet (offline). */
    private renderPendingSubmit(): void {
        const section = this.reset();
        const p = document.createElement('p');
        p.className = 'screen-loading';
        p.textContent = 'Saved — your meal estimate is queued and will be sent as soon as you’re online. You can leave this screen; we’ll notify you when it’s ready.';
        section.appendChild(p);
    }

    /** Story 362: the server refused the queued submit for good — its words, verbatim, and a way to let it go. */
    private renderRejectedSubmit(submit: EstimateSubmitEntry): void {
        const section = this.reset();
        const pre = document.createElement('pre');
        pre.className = 'screen-error';
        pre.textContent = `Estimate not sent:\n${submit.rejected_reason}`;
        section.appendChild(pre);
        section.appendChild(this.actions([
            {
                label: 'Discard',
                onClick: () => void safeExec(this, this.log, async () => {
                    await deleteEstimateSubmit(submit.id);
                    await exitFlow(`/health/day/${encodeURIComponent(submit.date)}`);
                }),
            },
        ]));
    }

    private renderFailed(job: EstimateJob): void {
        const section = this.reset();
        const error = job.error ?? 'Unknown error';
        // Story 241: GPU contention is deferrable, not a broken estimate — the
        // drain stores a `gpu_contended:` prefix. Give the (admin) user the
        // context to act: retry, or pause Immich's indexing first.
        const contended = error.startsWith(`${GPU_CONTENDED_REASON}:`);
        if (contended) {
            const hint = document.createElement('p');
            hint.className = 'estimate-review-hint';
            hint.textContent = 'The GPU was busy with Immich photo indexing, so the estimate was held off rather than risk a crash. Retry now — or pause Immich’s jobs first if it’s still indexing.';
            section.appendChild(hint);
        }
        const pre = document.createElement('pre');
        pre.className = 'screen-error';
        pre.textContent = `Estimate ${contended ? 'delayed — GPU busy' : 'failed'}:\n${error}`;
        section.appendChild(pre);
        section.appendChild(this.actions([
            { label: 'Retry', primary: true, onClick: () => this.retry(job.id) },
            { label: 'Discard', onClick: () => this.archive(job) },
        ]));
    }

    /**
     * Story 423 — the draft, editable. A meal goes straight to the line-set editor; a
     * proposed single food is reviewed in the food editor first, since its values are the
     * estimate, then becomes the one line logged. A library food needs no review.
     */
    private renderDone(job: EstimateJob, result: EstimateJobResult): void {
        const section = this.reset();
        this.renderPhoto(section, job, result);
        this.renderTotal(section, job, result);

        if (result.kind === 'food_item' && !isLibraryFood(result.food_item)) {
            const editor = document.createElement('food-editor') as FoodEditor;
            editor.setAttribute('mode', 'estimate-draft');
            editor.setAttribute('provenance', PROVENANCE_KIND[result.resolution.provenance]);
            customElements.upgrade(editor);
            editor.food = result.food_item;
            const amount = result.resolution.amount;
            const resolution = result.resolution;
            editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_SAVE, (e: FoodEditorSaveEvent) => {
                const food: NewFoodItem = e.detail.food;
                e.detail.respondWith = Promise.resolve().then(() => {
                    const line = draftLine(food, amount, resolution);
                    this.renderDraft(section, job, food.display_name, [line], null);
                });
            });
            section.append(editor, this.actions([{ label: 'Discard', onClick: () => this.archive(job) }]));
            return;
        }

        const lines = result.kind === 'meal'
            ? result.ingredients.map((ing) => draftLine(ing.food_item, ing.amount, ing))
            : [draftLine(result.food_item, result.resolution.amount, result.resolution)];
        const name = result.kind === 'meal' ? result.meal_name : result.food_item.display_name;
        // Story 310: this estimate's ingredient set already exists as a meal.
        this.renderDraft(section, job, name, lines, result.kind === 'meal' ? job.duplicate_of ?? null : null);
    }

    /** The line-set editor on the draft's lines, and the Discard beside it. */
    private renderDraft(section: HTMLElement, job: EstimateJob, name: string, lines: LineView[], duplicate: DuplicateMealRef | null): void {
        section.querySelector('food-editor')?.remove();
        section.querySelector('.estimate-review-actions')?.remove();

        // Shown before the editor because it changes what Log means: three real outcomes, not a
        // yes/no — log tonight's weights onto the meal you already keep, adopt them as its own,
        // or log them alone (and, with "also save as a meal", keep both under a new name).
        let choice: DuplicateChoice = 'log_onto';
        if (duplicate) {
            const box = document.createElement('fieldset');
            box.className = 'estimate-review-duplicate-choice';
            box.append(this.duplicateBanner(duplicate));
            const options: Array<[DuplicateChoice, string]> = [
                ['log_onto', `Log onto ${duplicate.name}`],
                ['update_amounts', `Update ${duplicate.name}’s amounts, then log it`],
                ['new_log', 'Log it on its own'],
            ];
            for (const [value, label] of options) {
                const row = document.createElement('label');
                const radio = document.createElement('input');
                radio.type = 'radio';
                radio.name = 'duplicate-choice';
                radio.value = value;
                radio.checked = value === choice;
                radio.addEventListener('change', () => { if (radio.checked) choice = value; });
                row.append(radio, ` ${label}`);
                box.append(row);
            }
            section.append(box);
        }

        const editor = document.createElement('line-set-editor') as LineSetEditor;
        editor.setAttribute('mode', 'draft');
        customElements.upgrade(editor);
        // Eaten-at (story 260) defaults to now in the app zone; cleared, the log is unstamped.
        editor.value = { name, date: job.date, meal_type: job.meal_type, time: nowHHMM(getAppTimeZone()) };
        editor.lines = lines;
        const add = document.createElement('line-add-dialog') as LineAddDialog;
        editor.addEventListener(HEALTH_EVENTS.LINE_ADD_REQUEST, () => add.open(job.meal_type));
        add.addEventListener(HEALTH_EVENTS.LINE_PICKED, (e: LinePickedEvent) => {
            editor.addLine(e.detail.line);
            void safeExec(this, this.log, () => bindPickedBarcode(e.detail.line, e.detail.bind));
        });
        editor.addEventListener(HEALTH_EVENTS.LINE_SET_SAVE, (e: LineSetSaveEvent) => {
            e.detail.respondWith = this.save(job, e.detail, duplicate ? { meal: duplicate, choice } : null);
        });
        section.append(editor, add, this.actions([{ label: 'Discard', onClick: () => this.archive(job) }]));
    }

    /** Story 310 — names the existing meal and how often it is actually used. */
    private duplicateBanner(duplicate: DuplicateMealRef): HTMLElement {
        const banner = document.createElement('p');
        banner.className = 'estimate-review-duplicate';
        banner.id = 'estimate-duplicate-note';
        const logged = duplicate.use_count === 1 ? 'logged once' : `logged ${duplicate.use_count} times`;
        banner.textContent = `Same ingredients as your existing meal “${duplicate.name}” (${logged}).`;
        return banner;
    }

    /**
     * The estimate itself — photo, name, ingredients, total. Shared by the
     * outstanding-review render and story 294's discarded one, so a job you
     * threw away looks like what it was rather than a second, different screen.
     */
    private renderPhoto(section: HTMLElement, job: EstimateJob, result: EstimateJobResult): void {
        if (!job.image_path) return;
        const img = document.createElement('img');
        img.className = 'estimate-review-image';
        img.src = FilesService.variantUrl(job.image_path, 'display.jpg');
        img.alt = result.kind === 'meal' ? result.meal_name : result.food_item.display_name;
        section.appendChild(img);
    }

    /**
     * The estimate's own total, and story 319's warnings: a food that won a tie among
     * same-name library rows that disagree on kcal says by how much.
     */
    private renderTotal(section: HTMLElement, job: EstimateJob, result: EstimateJobResult): void {
        const total = document.createElement('p');
        total.className = 'estimate-review-total';
        total.append(`~${Math.round(resultKcal(result))} kcal estimated · for ${job.meal_type} on `);
        // Story 279: own element so the visual baselines can mask the slot date
        // (which moves every day) while still pinning the kcal figure's pixels.
        const slotDate = document.createElement('span');
        slotDate.id = 'estimate-slot-date';
        slotDate.textContent = job.date;
        total.appendChild(slotDate);
        section.appendChild(total);

        const foods = result.kind === 'meal'
            ? result.ingredients.map((ing) => ({ name: ing.food_item.display_name, resolution: ing }))
            : [{ name: result.food_item.display_name, resolution: result.resolution }];
        const warnings = document.createElement('ul');
        warnings.className = 'estimate-review-divergence';
        for (const { name, resolution } of foods) {
            const badge = createDivergenceBadge(resolution);
            if (!badge) continue;
            const li = document.createElement('li');
            li.append(`${name} `, badge);
            warnings.append(li);
        }
        if (warnings.children.length > 0) section.appendChild(warnings);
    }

    private renderResultSummary(section: HTMLElement, job: EstimateJob, result: EstimateJobResult): void {
        this.renderPhoto(section, job, result);

        const title = document.createElement('h2');
        title.textContent = result.kind === 'meal' ? result.meal_name : result.food_item.display_name;
        section.appendChild(title);

        if (result.kind === 'meal') {
            const list = document.createElement('ul');
            list.className = 'estimate-review-ingredients';
            for (const ing of result.ingredients) {
                const li = document.createElement('li');
                const name = document.createElement('span');
                name.className = 'ingredient-name';
                // Story 368: the food's own unit — ml used to read "g".
                const unit = ing.food_item.base_unit === 'piece' ? '×' : ing.food_item.base_unit === 'ml' ? ' ml' : 'g';
                name.textContent = `${ing.food_item.display_name} — ${Math.round(ing.amount)}${unit}`;
                const badge = document.createElement('span');
                badge.className = `provenance-badge ${PROVENANCE_CLASS[ing.provenance]}`;
                badge.textContent = PROVENANCE_LABELS[ing.provenance];
                li.append(name, badge);
                // Story 319: this row won a tie among same-name rows that disagree on kcal.
                const divergence = createDivergenceBadge(ing);
                if (divergence) li.append(divergence);
                list.appendChild(li);
            }
            section.appendChild(list);
        } else {
            const badge = document.createElement('span');
            badge.className = `provenance-badge ${PROVENANCE_CLASS[result.resolution.provenance]}`;
            badge.textContent = PROVENANCE_LABELS[result.resolution.provenance];
            section.appendChild(badge);
            const divergence = createDivergenceBadge(result.resolution);
            if (divergence) section.appendChild(divergence);
        }

        const total = document.createElement('p');
        total.className = 'estimate-review-total';
        total.append(`~${Math.round(resultKcal(result))} kcal · for ${job.meal_type} on `);
        // Story 279: own element so the visual baselines can mask the slot date
        // (which moves every day) while still pinning the kcal figure's pixels.
        const slotDate = document.createElement('span');
        slotDate.id = 'estimate-slot-date';
        slotDate.textContent = job.date;
        total.appendChild(slotDate);
        section.appendChild(total);
    }

    private actions(buttons: Array<{ label: string; primary?: boolean; onClick: () => void }>): HTMLElement {
        const row = document.createElement('div');
        row.className = 'estimate-review-actions';
        for (const b of buttons) {
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = b.primary ? 'btn-primary' : 'btn-secondary';
            btn.textContent = b.label;
            btn.addEventListener('click', b.onClick);
            row.appendChild(btn);
        }
        return row;
    }

    /**
     * Log the draft (418 #7): its proposed foods are created here, by the saves, and nowhere
     * else. With "also save as a meal" the meal is created first — under the name as edited,
     * with the estimate's photo as its cover — and the log is made from it, so each proposed
     * food is created once and the log links to the meal. A duplicate (story 310) logs onto
     * the meal it matches, optionally adopting these amounts as its own first. The job is
     * recorded last; a failure there leaves the log standing and says so.
     */
    private async save(job: EstimateJob, d: LineSetValue, duplicate: { meal: DuplicateMealRef; choice: DuplicateChoice } | null): Promise<void> {
        return safeExec(this, this.log, async () => {
            const name = d.name.trim() || null;
            let lines: LineInput[] = d.lines.map(toLineInput);
            let mealId: string | null = null;

            if (d.also_update_meal) {
                const meal = await HealthService.createMeal({
                    id: uuidv7(),
                    name: name ?? 'Estimated meal',
                    image_path: job.image_path ?? null,
                    ingredients: lines.map(({ food_item_id, new_food_item, amount }) => ({ food_item_id, new_food_item, amount })),
                });
                mealId = meal.id;
                // The meal keeps the lines' order, so line i is ingredient i.
                lines = lines.map((line, i) => ({ amount: line.amount, food_item_id: meal.ingredients[i].food_item_id, ...(line.nutrition ? { nutrition: line.nutrition } : {}) }));
            } else if (duplicate && duplicate.choice !== 'new_log') {
                mealId = duplicate.meal.id;
                if (duplicate.choice === 'update_amounts') {
                    const meal = await HealthService.getMeal(mealId);
                    await HealthService.replaceMeal(mealId, {
                        name: meal.name, notes: meal.notes, image_path: meal.image_path,
                        ingredients: lines.map(({ food_item_id, new_food_item, amount }) => ({ food_item_id, new_food_item, amount })),
                    });
                }
            }

            await HealthService.createLog({
                id: uuidv7(),
                date: d.date,
                meal_type: d.meal_type,
                consumed_at: d.time ? dateAndTimeToInstant(d.date, d.time, getAppTimeZone()) : null,
                meal_id: mealId,
                name,
                lines,
            });
            await HealthService.recordEstimateJobMeal(job.id, mealId);
            // Story 291: exit the add-food flow rather than pushing the day on top of it. In-app
            // the day is already below this screen; arriving from a notification it is not, so
            // `exitFlow` puts it there.
            await exitFlow(`/health/day/${encodeURIComponent(d.date)}`);
        });
    }

    private archive(job: EstimateJob): void {
        void safeExec(this, this.log, async () => {
            await HealthService.archiveEstimateJob(job.id);
            await exitFlow(`/health/day/${encodeURIComponent(job.date)}`);
        });
    }

    private retry(jobId: string): void {
        // The SERVER job id (from the fetched job) — not this.jobIdValue, which
        // may be a client_submit_id on the story-221 pending path.
        void safeExec(this, this.log, async () => {
            await HealthService.retryEstimateJob(jobId);
            await this.load();
        });
    }
}

if (!customElements.get('health-estimate-review-screen')) {
    customElements.define('health-estimate-review-screen', HealthEstimateReviewScreen);
}
